        i = 0;
        while (i < n) {
            grid[i] = 0;
            if (row1[i] == "1") {
                grid[i] = 1;
            }
            i = i + 1;
        }
        i = 0;
        while (i < n) {
            grid[n + i] = 0;
            if (row2[i] == "1") {
                grid[n + i] = 1;
            }
            i = i + 1;
        }

