function canBuild(left, right, values, memo) {
    if (left > right) {
        return 1;
    }

    if (left == right) {
        return 1;
    }

    memo_key = left * 1000 + right;
    if (memo[memo_key] == 1) {
        return 1;
    }
    if (memo[memo_key] == 0) {
        return 0;
    }

    root_idx = left;
    while (root_idx <= right) {
        root_val = values[root_idx];
        can_connect_left = 1;
        can_connect_right = 1;

        if (root_idx > left) {
            can_connect_left = 0;
            i = left;
            while (i < root_idx) {
                if (gcd(root_val, values[i]) > 1) {
                    can_connect_left = 1;
                }
                i = i + 1;
            }
        }

        if (root_idx < right) {
            can_connect_right = 0;
            i = root_idx + 1;
            while (i <= right) {
                if (gcd(root_val, values[i]) > 1) {
                    can_connect_right = 1;
                }
                i = i + 1;
            }
        }

        if (can_connect_left && can_connect_right) {
            left_ok = canBuild(left, root_idx - 1, values, memo);
            right_ok = canBuild(root_idx + 1, right, values, memo);

            if (left_ok && right_ok) {
                memo[memo_key] = 1;
                return 1;
            }
        }

        root_idx = root_idx + 1;
    }

    memo[memo_key] = 0;
    return 0;
}
function gcd(a, b) {
    while (b != 0) {
        temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

