function int_to_string(num) {
    if (num == 0) {
        return "0";
    }

    result = "";
    is_negative = 0;
    if (num < 0) {
        is_negative = 1;
        num = 0 - num;
    }

    digits = [];
    digit_count = 0;
    temp = num;
    while (temp > 0) {
        digits[digit_count] = temp % 10;
        temp = (temp - (temp % 10)) / 10;
        digit_count = digit_count + 1;
    }

    if (is_negative == 1) {
        result = result + "-";
    }

    i = digit_count - 1;
    while (i >= 0) {
        digit_val = digits[i];
        if (digit_val == 0) { result = result + "0"; }
        if (digit_val == 1) { result = result + "1"; }
        if (digit_val == 2) { result = result + "2"; }
        if (digit_val == 3) { result = result + "3"; }
        if (digit_val == 4) { result = result + "4"; }
        if (digit_val == 5) { result = result + "5"; }
        if (digit_val == 6) { result = result + "6"; }
        if (digit_val == 7) { result = result + "7"; }
        if (digit_val == 8) { result = result + "8"; }
        if (digit_val == 9) { result = result + "9"; }
        i = i - 1;
    }

    return result;
}

